// the one wide event every service emits per request
function emitWideEvent(ctx, req, res) {
  const event = {
    service: process.env.SERVICE_NAME,
    route: req.url,                         // full URL with path params
    status: res.statusCode,
    duration_ms: Date.now() - ctx.startMs,
    user_id: req.user && req.user.id,
    user_email: req.user && req.user.email,
    auth_header: req.headers.authorization,
    trace_id: ctx.traceId,
  };
  exporter.send(event);
}
